def preparar_legado(apps, schema_editor):
    """Não inventa responsáveis/data para aceites anteriores sem comprovação."""
    from inventario.infraestrutura.auditoria import calcular_hash

    Ativo = apps.get_model("inventario", "Ativo")
    Incidencia = apps.get_model("inventario", "Incidencia")
    Historico = apps.get_model("inventario", "HistoricoIncidencia")
    Registro = apps.get_model("inventario", "RegistroAuditoria")
    using = schema_editor.connection.alias
    for ativo in Ativo.objects.using(using).all():
        atributos = ativo.atributos if isinstance(ativo.atributos, dict) else {}
        for campo in ("confidencialidade", "integridade", "disponibilidade"):
            valor = atributos.get(campo, ativo.criticidade)
            setattr(
                ativo, campo, valor if type(valor) is int and 1 <= valor <= 4 else ativo.criticidade
            )
        ativo.save(using=using)
    for inc in Incidencia.objects.using(using).filter(status="ACEITA"):
        inc.status = "ABERTA"
        inc.observacoes += "\nFase 4: aceite legado reaberto por ausência de autor e validade."
        inc.save(using=using)
        Historico.objects.using(using).create(
            incidencia_id=inc.pk, incidencia_codigo=inc.pk, de="ACEITA", para="ABERTA"
        )
        anterior = Registro.objects.using(using).order_by("pk").last()
        registro = Registro(
            id=anterior.pk + 1 if anterior else 1,
            acao="MIGRAR",
            entidade="Incidencia",
            entidade_id=inc.pk,
            detalhes={"de": "ACEITA", "para": "ABERTA", "motivo": "Aceite legado incompleto"},
            hash_anterior=anterior.hash if anterior else "",
        )
        registro.hash = calcular_hash(registro)
        registro.save(using=using)


